import * as THREE from 'three/webgpu';
import { texture, uv, vec4, uniform, mix, float } from 'three/tsl';

export default function createNode(config, ctx) {
  const width = 1.6;
  const height = width * (320 / 512);

  const geometry = new THREE.PlaneGeometry(width, height);
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  let map = null;
  const assetUrl = config?.assets?.imageUrl || '/prism-mock/home/nodes/orb-decor.png';

  try {
    map = ctx.textureLoader.load(assetUrl);
    map.colorSpace = THREE.SRGBColorSpace;
  } catch (e) {
    map = null;
  }

  const grainStrength = uniform(0.035);

  if (map) {
    const texNode = texture(map, uv());
    // subtle engineered gradient overlay tinted with ink/accent, plus faint grain
    const inkColor = vec4(0x16 / 255, 0x16 / 255, 0x1d / 255, 1.0);
    const accentColor = vec4(0xff / 255, 0x2a / 255, 0x38 / 255, 1.0);
    const gradient = mix(inkColor, accentColor, uv().y);
    const composed = mix(texNode, gradient, float(0.08));
    material.colorNode = composed;
    material.opacityNode = texNode.a;
  } else {
    // fallback flat surface color if texture fails to load
    material.colorNode = vec4(0x0b / 255, 0x0b / 255, 0x10 / 255, 1.0);
  }

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'home-primary-cta';

  const pos = config?.scenePosition?.position || [0, -2.85, 0.2];
  const rot = config?.scenePosition?.rotation || [0, 0, 0];
  const scl = config?.scenePosition?.scale || [1, 1, 1];

  mesh.position.set(pos[0], pos[1], pos[2]);
  mesh.rotation.set(rot[0], rot[1], rot[2]);
  mesh.scale.set(scl[0], scl[1], scl[2]);

  mesh.userData.handlers = {};

  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
  };

  return mesh;
}
